package org.example.image;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;

// 11-2 파일을 디스크에 쓰고 읽는 일만 한다(무엇을 허용할지는 ImageService가 정한다).
// 저장 위치는 설정(app.upload-dir)으로 뺀다 — 서버마다, 테스트마다 다를 수 있다.
@Component
public class ImageStorage {

    private final Path root;

    public ImageStorage(@Value("${app.upload-dir:uploads}") String uploadDir) {
        this.root = Path.of(uploadDir).toAbsolutePath().normalize();
    }

    public void save(String storedName, byte[] bytes) {
        try {
            Files.createDirectories(root);
            Files.write(root.resolve(storedName), bytes);
        } catch (IOException e) {
            throw new UncheckedIOException("이미지를 저장하지 못했습니다.", e);
        }
    }

    // storedName은 서버가 지은 이름(무작위+확장자)만 들어온다 — 컨트롤러가 형식을 먼저 확인한다
    public Path pathOf(String storedName) {
        return root.resolve(storedName);
    }

    public void delete(String storedName) {
        try {
            Files.deleteIfExists(root.resolve(storedName));
        } catch (IOException ignored) {
            // 지우지 못한 파일은 남아도 된다(어디에도 연결되지 않는다)
        }
    }
}

