package org.example.image;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import org.example.member.Member;
import org.example.post.Post;

import java.time.LocalDateTime;

// 11-2 첨부 이미지(V20) — 파일 내용은 디스크에, 이 행은 파일의 이름표
@Entity
@Table(name = "post_image")
public class PostImage {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "uploader_id", nullable = false)
    private Member uploader;

    // 업로드 직후엔 null — 글을 쓸 때 attachTo()로 연결한다
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "post_id")
    private Post post;

    @Column(name = "stored_name", nullable = false, length = 64)
    private String storedName;

    @Column(name = "original_name", nullable = false)
    private String originalName;

    @Column(name = "content_type", nullable = false, length = 50)
    private String contentType;

    @Column(name = "size_bytes", nullable = false)
    private Integer sizeBytes;

    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    protected PostImage() {
        // JPA
    }

    public PostImage(Member uploader, String storedName, String originalName, String contentType,
                     int sizeBytes, LocalDateTime now) {
        this.uploader = uploader;
        this.storedName = storedName;
        this.originalName = originalName;
        this.contentType = contentType;
        this.sizeBytes = sizeBytes;
        this.createdAt = now;
    }

    public void attachTo(Post post) {
        this.post = post;
    }

    // 응답에 내려 주는 주소 — 파일은 GET /api/images/{storedName}으로 받는다
    public String url() {
        return "/api/images/" + storedName;
    }

    public Long getId() {
        return id;
    }

    public Member getUploader() {
        return uploader;
    }

    public Post getPost() {
        return post;
    }

    public String getStoredName() {
        return storedName;
    }

    public String getOriginalName() {
        return originalName;
    }

    public String getContentType() {
        return contentType;
    }

    public Integer getSizeBytes() {
        return sizeBytes;
    }
}

